const reduceMotion=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function commitDragMotion(d){const entries=d.type==='node'?[{node:d.node},...(d.group||[])]:d.type==='topic'?[{node:d.topic}]:[];if(d.type==='node'&&d.group)for(const item of d.group){item.node.x=item.x+d.node.x-d.x;item.node.y=item.y+d.node.y-d.y}for(const item of entries){const el=d.type==='topic'?$('[data-topic="'+item.node.id+'"]'):$('[data-node="'+item.node.id+'"]');if(el){el.style.left=item.node.x+'px';el.style.top=item.node.y+'px';el.style.translate='';}item.drawX=item.node.x;item.drawY=item.node.y;}d.drawX=d.type==='node'?d.node.x:d.type==='topic'?d.topic.x:d.x;d.drawY=d.type==='node'?d.node.y:d.type==='topic'?d.topic.y:d.y;}
function stopDragMotion(){if(activeDragMotion){commitDragMotion(activeDragMotion);activeDragMotion.cancelled=true;cancelAnimationFrame(activeDragMotion.frame||0);activeDragMotion=null}}
function followDrag(d){
 if(d.frame||d.cancelled)return;activeDragMotion=d;let last=performance.now();
 const tick=now=>{if(d.cancelled)return;const dt=Math.min(40,now-last);last=now;const ease=reduceMotion()?1:1-Math.exp(-Math.max(8,dt)/(d.type==='topic'?9:d.type==='node'?16:20)),model=d.type==='node'?d.node:d.type==='topic'?d.topic:d.type==='topicPan'?topicPan:pan;
 model.x+=(d.targetX-model.x)*ease;model.y+=(d.targetY-model.y)*ease;
 const el=d.type==='node'?$(`[data-node="${d.node.id}"]`):d.type==='topic'?$(`[data-topic="${d.topic.id}"]`):null;
 if(el)el.style.translate=(model.x-(d.drawX??d.x))+'px '+(model.y-(d.drawY??d.y))+'px';
 if(d.type==='node'&&d.group){for(const item of d.group){item.node.x=item.x+model.x-d.x;item.node.y=item.y+model.y-d.y;const other=$(`[data-node="${item.node.id}"]`);if(other)other.style.translate=(item.node.x-(item.drawX??item.x))+'px '+(item.node.y-(item.drawY??item.y))+'px';}}
 if(d.type==='node'){renderBoardWires();if(d.node.type==='ink'||d.group?.some(item=>item.node.type==='ink'))renderInk()}else if(d.type==='topic'){renderScheduleWires()}else if(d.type==='topicPan'){updateTopicPan();renderScheduleWires()}else updateTransform();
 const distance=Math.hypot(d.targetX-model.x,d.targetY-model.y);
 if(distance>.05){d.frame=requestAnimationFrame(tick)}else{model.x=d.targetX;model.y=d.targetY;commitDragMotion(d);d.frame=0;if(d.released&&!['pan','topicPan'].includes(d.type))save();if(activeDragMotion===d)activeDragMotion=null}
 };d.frame=requestAnimationFrame(tick);
}
function moveCamera(x,y,z,animate=true){cameraTarget={x,y,z};if(!animate||reduceMotion()){cancelAnimationFrame(cameraFrame);cameraFrame=0;pan={x,y};zoom=z;updateTransform();return}if(cameraFrame)return;let last=performance.now();const tick=now=>{const dt=Math.min(40,now-last);last=now;const ease=1-Math.exp(-Math.max(8,dt)/28);pan.x+=(cameraTarget.x-pan.x)*ease;pan.y+=(cameraTarget.y-pan.y)*ease;zoom+=(cameraTarget.z-zoom)*ease;updateTransform();if(Math.abs(pan.x-cameraTarget.x)+Math.abs(pan.y-cameraTarget.y)+Math.abs(zoom-cameraTarget.z)*100>.08)cameraFrame=requestAnimationFrame(tick);else{pan={x:cameraTarget.x,y:cameraTarget.y};zoom=cameraTarget.z;updateTransform();cameraFrame=0}};cameraFrame=requestAnimationFrame(tick)}
