function moveWireHand(x,y){const hand=$('#wireDragHand');if(!hand||hand.classList.contains('releasing'))return;const now=performance.now(),last=wireHandLast||{x,y,time:now-16,angle:0},dt=Math.max(10,now-last.time),vx=(x-last.x)/dt,vy=(y-last.y)/dt,target=reduceMotion()?0:Math.max(-8,Math.min(8,vx*10-vy*4)),angle=last.angle+(target-last.angle)*.18;hand.style.left=(x-8.5)+'px';hand.style.top=(y-17)+'px';hand.style.setProperty('--hand-tilt',angle+'deg');wireHandLast={x,y,time:now,angle};clearTimeout(wireHandRestTimer);wireHandRestTimer=setTimeout(()=>{if(hand.isConnected)hand.style.setProperty('--hand-tilt','0deg')},100)}
