function validWorkspace(s){
 if(!s||s.version!==1||!Array.isArray(s.boards)||!s.boards.length||s.boards.length>200||!Array.isArray(s.topics)||s.topics.length>1000)return false;
 const boardIds=new Set();
 for(const b of s.boards){if(!b||typeof b.id!=='string'||typeof b.title!=='string'||!Array.isArray(b.nodes)||!Array.isArray(b.edges)||!Array.isArray(b.strokes)||b.nodes.length>2000||boardIds.has(b.id))return false;boardIds.add(b.id);for(const n of b.nodes)if(!n||typeof n.id!=='string'||!['note','sticky','text','image','video','link','shape','table','sequencer','stamp','clock','soundscape'].includes(n.type)||!Number.isFinite(n.x)||!Number.isFinite(n.y)||!Number.isFinite(n.w)||n.w<50||n.w>3000)return false;for(const p of b.strokes)if(!p||!Array.isArray(p.points)||p.points.some(v=>!Array.isArray(v)||!Number.isFinite(v[0])||!Number.isFinite(v[1])))return false}
 for(const t of s.topics)if(!t||typeof t.id!=='string'||typeof t.title!=='string'||!boardIds.has(t.boardId)||!Array.isArray(t.pointers)||(t.date&&!/^\d{4}-\d{2}-\d{2}$/.test(t.date)))return false;
 if(s.sequences!==undefined){if(!Array.isArray(s.sequences)||s.sequences.length>1000)return false;for(const seq of s.sequences){if(!seq||typeof seq.id!=='string'||typeof seq.contentId!=='string'||typeof seq.boardId!=='string'||typeof seq.contentTitle!=='string'||!Array.isArray(seq.shots)||seq.shots.length>2000||typeof seq.archived!=='boolean')return false;for(const shot of seq.shots)if(!shot||typeof shot.id!=='string'||typeof shot.notes!=='string'||typeof shot.done!=='boolean')return false}}
 return true;
}
function save(){state.updatedAt=Date.now();$('#saveState').innerHTML='<span></span>Saving…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>{saveTimer=null;try{localStorage.setItem(STORE,JSON.stringify(state));$('#saveState').innerHTML='<span></span>All changes saved';if(cloudReady&&!cloudConflict){clearTimeout(cloudTimer);cloudTimer=setTimeout(()=>syncCloud(),1600)}}catch{$('#saveState').textContent='Storage full — export a backup';toast('Device storage is full. Export a workspace backup before adding more images.')}},180)}
