function formatDate(date,options={month:'short',day:'numeric'}){return date?parseDate(date).toLocaleDateString('en-US',options):'Unscheduled'}
function formatTime(time){if(!time)return 'Time not set';const [h,m]=time.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'AM':'PM'}`}
function monthLabel(){return month.toLocaleDateString('en-US',{month:'long',year:'numeric'})}
function inMonth(date){return date&&parseDate(date).getMonth()===month.getMonth()&&parseDate(date).getFullYear()===month.getFullYear()}
function safeURL(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
function safeImage(value){return /^data:image\/(png|jpeg|webp|gif);base64,/.test(value)||value==='./cozy-world.svg'?value:safeURL(value)}
function youtubeID(url){try{const u=new URL(url);if(u.hostname==='youtu.be')return /^[\w-]{11}$/.test(u.pathname.slice(1))?u.pathname.slice(1):null;if(['youtube.com','www.youtube.com','m.youtube.com'].includes(u.hostname)){const id=u.searchParams.get('v')||u.pathname.split('/')[2];return /^[\w-]{11}$/.test(id||'')?id:null}}catch{}return null}
