function renderTools(){const tools=[['select','cursor','Select · V'],['hand','hand','Pan · H'],null,['text','text','Text · T'],['note','note','Sticky note · N'],['pen','pen','Draw · P'],['shape','shape','Shape · S'],['cut','knife','Cut wires · K'],null,['image','image','Image · I'],['link','link','Reference · L'],['table','table','Table'],['sequencer','sequence','Create shot sequencer'],null,['stamp','stamp','Stamps'],['clock','clock','Focus clock'],['sound','music','Soundscapes']];$('#toolbar').innerHTML=tools.map(t=>t?`<button class="icon-btn ${tool===t[0]?'selected':''}" data-tool="${t[0]}" title="${t[2]}" data-label="${t[2]}" aria-label="${t[2]}">${icon(t[1])}</button>`:'<span class="divider"></span>').join('');$$('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));$('#canvas').className='canvas tool-'+tool;renderToolOptions();Soundscape.refresh(false);if(StudioPointer.last)StudioPointer.move(StudioPointer.last)}
function setTool(t){if(t==='stamp'&&tool==='stamp')t='select';$('#stampCursor')?.remove();if(t==='note'&&tool==='note')t='select';CanvasEditor.stopStickyCursor();CanvasEditor.finish();cancelConnections();tool=t;if(!['select','hand'].includes(t)){CanvasSelection.one(null);$('.empty-board-note')?.remove();}if(t==='stamp')StampKit.pickerOpen=true;if(t==='note')CanvasEditor.activateSticky();else if(t==='clock'){FocusClock.show();tool='select'}else if(t==='sound'){Soundscape.open();tool='select'}else if(t==='text'){selectedNode=null;selectNode(null)}else if(t==='table'){tool='select';CanvasEditor.tableDialog()}else if(t==='sequencer'){CanvasEditor.createSequencer();tool='select'}else if(t==='image'){$('#imageInput').click();tool='select'}else if(t==='link'){openReference();tool='select'}renderTools();if(t==='stamp')$('#canvasHint').textContent='Right-click, Escape, or the stamp tool to finish';else if(t!=='note')$('#canvasHint').textContent='Drag to pan · Shift + drag to select · Ctrl + Shift + drag for lasso · Right-drag to cut wires'}
function renderToolOptions(){if(tool==='stamp'){StampKit.options();return}if(tool==='note'){CanvasEditor.stickyOptions();return}if(CanvasSelection.ids.size>1||CanvasSelection.showFormat){$('#toolOptions').innerHTML='';return}if(tool==='pen'){CanvasEditor.penOptions();return}if(tool==='shape'){$('#toolOptions').innerHTML=`<div class="shape-palette" role="toolbar" aria-label="Shapes">${[['rectangle','rectangle','Rectangle'],['circle','ellipse','Ellipse'],['diamond','diamond','Diamond'],['triangle','triangle','Triangle'],['rounded','roundedrect','Rounded rectangle'],['hexagon','hexagon','Hexagon'],['parallelogram','parallelogram','Parallelogram'],['cylinder','cylinder','Cylinder'],['speech','speech','Speech bubble'],['star','star','Star'],['cloud','cloud','Cloud'],['arrow','blockarrow','Arrow']].map(([kind,glyph,label])=>`<button class="icon-btn ${shapeType===kind?'selected':''}" data-shape="${kind}" aria-label="Draw ${label}" title="${label}">${icon(glyph)}</button>`).join('')}</div><span class="muted small-text">Drag to draw</span>`;$$('[data-shape]').forEach(button=>button.onclick=()=>{shapeType=button.dataset.shape;renderToolOptions()});return}if(tool==='text'){$('#toolOptions').innerHTML='<span class="text-placement-tip">Click anywhere to place text. Start typing right on the canvas.</span>';return}const n=board().nodes.find(n=>n.id===selectedNode);if(n&&['text','note','sticky','shape'].includes(n.type)){CanvasEditor.formatting(n);return}$('#toolOptions').innerHTML=''}
function addNode(type,position,extra={}){checkpoint();const c=$('#canvas'),p=position||{x:(c.clientWidth/2-pan.x)/zoom-125,y:(c.clientHeight/2-pan.y)/zoom-100};const n={id:uid(),type,x:p.x,y:p.y,w:type==='table'?340:250,title:{text:'A thought worth exploring',note:'What if…',shape:'A new step',table:'Research at a glance',sticky:'Don’t lose this thought.'}[type]||'Untitled reference',label:type==='text'?'STORY NOTES':type==='table'?'RESEARCH TABLE':'A NEW IDEA',text:type==='text'?'Double-click to write, add pointers, and find your thread.':'',...extra};if(type==='shape')n.shape=shapeType;if(type==='table'&&!n.rows)n.rows=[['Point','Reference'],['Your first insight','Source or link'],['Another thread','Source or link']];board().nodes.push(n);CanvasSelection.one(n.id);renderNodes();renderToolOptions();save();return n}
function removeNode(id){checkpoint();board().nodes=board().nodes.filter(n=>n.id!==id);board().edges=board().edges.filter(e=>e.from!==id&&e.to!==id);selectedNode=null;renderNodes();save();toast('Card removed · Ctrl Z to undo')}
function duplicateNode(id){const original=board().nodes.find(n=>n.id===id);if(!original)return;if(original.type==='clock'){toast('Use the existing focus clock.');return}if(original.type==='sequencer'){toast('Each board has one shot sequencer. Reuse the existing shot list.');return}checkpoint();const n={...clone(original),id:uid(),x:original.x+32,y:original.y+32};board().nodes.push(n);CanvasSelection.one(n.id);renderNodes();save();toast('Card duplicated')}
function disconnectNode(id){const edges=board().edges;if(!edges.some(e=>e.from===id||e.to===id))return toast('This card has no connections yet');checkpoint();board().edges=edges.filter(e=>e.from!==id&&e.to!==id);renderBoardWires();save();beep('disconnect');toast('Card disconnected')}
function editNode(id){const n=board().nodes.find(n=>n.id===id);if(!n)return;if(['text','note','sticky','shape','table'].includes(n.type)){CanvasEditor.edit(id);return}const isText=['text','note','sticky','link'].includes(n.type);showModal(`<div class="modal-header"><div><div class="eyebrow">MAKE THE IDEA YOURS</div><h2 id="modalTitle">${n.type==='table'?'A little order for your research.':'Follow that thought.'}</h2></div>${closeButton()}</div><form id="nodeForm"><label class="field"><span>${n.type==='image'?'Image caption':'Title'}</span><input id="nodeTitle" required maxlength="500" value="${escapeHTML(n.title)}"></label>${isText?`<label class="field"><span>Notes</span><textarea id="nodeText" rows="4" maxlength="10000">${escapeHTML(n.text||'')}</textarea></label>`:''}${n.type==='text'?`<label class="field"><span>Talking points · one per line</span><textarea id="nodeBullets" rows="4" maxlength="10000">${escapeHTML((n.bullets||[]).join('\n'))}</textarea></label>`:''}${['link','video'].includes(n.type)?`<label class="field"><span>Reference URL</span><input id="nodeURL" type="url" required value="${escapeHTML(n.url)}"></label>`:''}${n.type==='table'?`<label class="field"><span>Table content</span><textarea id="nodeRows" rows="7" maxlength="20000">${escapeHTML((n.rows||[]).map(r=>r.join(' | ')).join('\n'))}</textarea></label><p class="field-help">One row per line. Separate columns with a | character. The first row is the heading.</p>`:''}<div class="modal-actions"><button type="button" class="secondary-btn" data-close>Cancel</button><button class="primary-btn">${icon('check')}Save card</button></div></form>`);$('#nodeForm').onsubmit=e=>{e.preventDefault();const url=$('#nodeURL')?.value;if(url&&!safeURL(url))return toast('Use a complete http or https URL');checkpoint();n.title=$('#nodeTitle').value.trim();if($('#nodeText'))n.text=$('#nodeText').value;if($('#nodeBullets'))n.bullets=$('#nodeBullets').value.split('\n').map(v=>v.trim()).filter(Boolean);if($('#nodeRows')){n.rows=$('#nodeRows').value.split('\n').map(r=>r.split('|').map(c=>c.trim()));const cols=Math.max(...n.rows.map(r=>r.length));n.rows.forEach(r=>{while(r.length<cols)r.push('')})}if(url){n.url=safeURL(url);const id=youtubeID(url);if(id&&n.type==='video'){n.src=`https://i.ytimg.com/vi/${id}/hqdefault.jpg`;n.demo=false}}closeModal();renderNodes();save()}}
function openReference(value=''){showModal(`<div class="modal-header"><div><div class="eyebrow">A SPARK FROM SOMEWHERE</div><h2 id="modalTitle">Bring your inspiration in.</h2><p>YouTube, articles, playlists, audio links. Keep the reference, skip the storage.</p></div>${closeButton()}</div><form id="referenceForm"><label class="field"><span>Reference URL</span><input type="url" id="referenceURL" required placeholder="https://youtube.com/watch?v=…" value="${escapeHTML(value)}"></label><label class="field"><span>A name to remember it by</span><input id="referenceTitle" required maxlength="200" placeholder="What caught your attention?"></label><label class="field"><span>Why it matters · optional</span><textarea id="referenceNote" rows="3" placeholder="A useful angle, a feeling, a detail…"></textarea></label><p class="field-help">YouTube video links automatically get a thumbnail. Audio stays a link—no bulky uploads.</p><div class="modal-actions"><button type="button" class="secondary-btn" data-close>Cancel</button><button class="primary-btn">${icon('plus')}Add to board</button></div></form>`);$('#referenceForm').onsubmit=e=>{e.preventDefault();const url=safeURL($('#referenceURL').value);if(!url)return toast('Use a complete http or https URL');const id=youtubeID(url),data={title:$('#referenceTitle').value.trim(),url,text:$('#referenceNote').value,src:id?`https://i.ytimg.com/vi/${id}/hqdefault.jpg`:undefined};closeModal();addNode(id?'video':'link',null,data);toast('Reference added to your board')}}
async function addImage(file,point){if(!file||!file.type.startsWith('image/'))return toast('Choose an image file');if(file.size>15*1024*1024)return toast('Choose an image smaller than 15 MB');try{const bitmap=await createImageBitmap(file),naturalWidth=bitmap.width,naturalHeight=bitmap.height;const canvas=document.createElement('canvas'),scale=Math.min(1,1600/Math.max(naturalWidth,naturalHeight));canvas.width=Math.round(naturalWidth*scale);canvas.height=Math.round(naturalHeight*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const src=canvas.toDataURL('image/webp',.82),view=$('#canvas'),maxW=Math.min(view.clientWidth*.4,view.clientWidth*.4/zoom),maxH=Math.min(view.clientHeight*.4,view.clientHeight*.4/zoom),imageScale=Math.min(1,Math.max(30,maxW-18)/naturalWidth,Math.max(20,maxH-70)/naturalHeight),w=Math.max(70,Math.min(maxW,naturalWidth*imageScale+18)),imageRatio=naturalHeight/naturalWidth;const position=point||{x:(view.clientWidth/2-pan.x)/zoom-w/2,y:(view.clientHeight/2-pan.y)/zoom-(naturalHeight*imageScale+58)/2};addNode('image',position,{src,title:(file.name||'Pasted image').replace(/\.[^.]+$/,''),w,imageRatio,imageHeight:naturalHeight*imageScale,initialWidth:w,label:'VISUAL REFERENCE'});toast('Image added and fitted to your workspace.')}catch{toast('This image could not be opened. Try a PNG, JPEG, or WebP.')}}
