function createBoard(){showModal(`<div class="modal-header"><div><div class="eyebrow">SOMETHING NEW IS BREWING</div><h2 id="modalTitle">Start a new project.</h2><p>One board for one idea. All the room you need to explore it.</p></div>${closeButton()}</div><form id="boardForm"><label class="field"><span>Project name</span><input id="newBoardName" required maxlength="120" placeholder="What are you curious about?"></label><div class="modal-actions"><button type="button" class="secondary-btn" data-close>Cancel</button><button class="primary-btn">${icon('plus')}Create project</button></div></form>`);$('#boardForm').onsubmit=e=>{e.preventDefault();const title=$('#newBoardName').value.trim();if(!title)return;checkpoint();const id=uid();state.boards.push({id,title,color:palette[state.boards.length%palette.length],nodes:[],edges:[],strokes:[]});closeModal();openBoard(id);toast('A fresh canvas. Make it yours.')}}
