function deleteBoard(id){if(state.boards.length===1)return toast('Keep one board in your workspace. Clear its cards to start fresh.');const b=state.boards.find(b=>b.id===id),linked=state.topics.filter(t=>t.boardId===id);showModal(`<div class="modal-header"><div><div class="eyebrow">MAKE A LITTLE ROOM</div><h2 id="modalTitle">Delete this research board?</h2><p>“${escapeHTML(b.title)}” and ${linked.length} linked topic${linked.length===1?'':'s'} will be removed. You can undo this with Ctrl Z.</p></div>${closeButton()}</div><div class="modal-actions"><button class="secondary-btn" data-close>Keep board</button><button class="primary-btn" style="background:#a16c52" id="confirmDeleteBoard">Delete board</button></div>`);$('#confirmDeleteBoard').onclick=()=>{checkpoint();state.boards=state.boards.filter(b=>b.id!==id);state.topics=state.topics.filter(t=>t.boardId!==id);state.sequences=sequences().filter(s=>s.boardId!==id);if(state.activeBoard===id)state.activeBoard=state.boards[0].id;closeModal();renderAll();save();toast('Board removed · Ctrl Z to undo')}}
