function renderStructure(){const field=$('#topicField'),width=field.clientWidth||800;const maxCardX=Math.max(25,width-305);$('#topicCards').innerHTML=state.topics.map((t,i)=>{const x=t.x??40,y=t.y??(82+i*235);return `<article class="topic-card ${t.id===selectedTopic?'active':''}" data-topic="${escapeHTML(t.id)}" style="--topic-color:${validColor(t.color)};left:${x}px;top:${y}px" tabindex="0" aria-label="${escapeHTML(t.title)}. Double-click to open research."><div class="topic-topline"><span class="platform-label">${icon('play')}${escapeHTML(t.platform.toUpperCase())}</span><span>${escapeHTML(t.format.toUpperCase())}</span></div><h3>${escapeHTML(t.title)}</h3><p>${escapeHTML(t.summary||'Your next story is waiting to be told.')}</p><div class="topic-meta"><span class="date-tag">${icon(t.date?'calendar':'clock')}${t.date?formatDate(t.date):'Not connected'}</span><button class="topic-board-link" data-content-board="${escapeHTML(t.boardId)}">${icon('board')}Open whiteboard</button></div><button class="topic-port ${scheduleConnect?.id===t.id?'armed':''}" data-port="${escapeHTML(t.id)}" aria-label="Connect ${escapeHTML(t.title)} to a date" title="Drag to a publishing date, or click then choose a date"></button></article>`}).join('');
 const height=Math.max(field.clientHeight,...state.topics.map((t,i)=>(t.y??(82+i*235))+240));$('#topicCards').style.height=height+'px';$('#scheduleWires').style.height='100%';$('#unscheduledCount').textContent=`${state.topics.filter(t=>!t.date).length} waiting for a date`;
 $$('.topic-card').forEach(el=>{el.onpointerdown=e=>topicDown(e,el.dataset.topic);el.ondblclick=e=>{if(e.target.closest('button'))return;openBoard(state.topics.find(t=>t.id===el.dataset.topic).boardId)};el.onkeydown=e=>{if(e.key==='Enter'&&e.target===el){e.preventDefault();openBoard(state.topics.find(t=>t.id===el.dataset.topic).boardId)}};el.oncontextmenu=e=>{e.preventDefault();topicMenu(e,el.dataset.topic)}});$$('[data-content-board]').forEach(b=>{b.onclick=e=>{e.stopPropagation();openBoard(b.dataset.contentBoard)}});$$('[data-topicmenu]').forEach(b=>b.onclick=e=>{e.stopPropagation();topicMenu(e,b.dataset.topicmenu)});$$('[data-port]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();e.stopPropagation();startScheduleWire(b.dataset.port,e)};b.onclick=e=>e.stopPropagation()});renderDates();updateTopicPan();requestAnimationFrame(renderScheduleWires)}
