function renderDates(){const days=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();$('#monthLabel').textContent=monthLabel();$('#dateList').innerHTML=Array.from({length:days},(_,i)=>{const d=new Date(month.getFullYear(),month.getMonth(),i+1),date=localDate(d),topics=state.topics.filter(t=>t.date===date),linked=topics.some(t=>t.id===selectedTopic);return `<button class="date-item ${linked?'linked':''}" data-date="${date}" aria-label="${formatDate(date,{weekday:'long',month:'long',day:'numeric'})}${topics.length?', '+topics.length+' scheduled':''}"><span class="date-port"></span><span class="date-number" aria-label="Date ${i+1}">${FocusClock.segments(String(i+1).padStart(2,'0'))}</span><span><span class="date-day">${d.toLocaleDateString('en-US',{weekday:'long'}).toUpperCase()}${date===localDate(today)?'<em>TODAY</em>':''}</span><span class="date-count" style="display:block">${topics.length?`${topics.length} CONTENT LINKED`:'CHANNEL OPEN'}</span></span>${linked?icon('check').replace('<svg','<svg class="date-check"'):''}</button>`}).join('');$$('[data-date]').forEach(el=>{el.onclick=()=>{if(scheduleConnect){connectTopic(scheduleConnect.id,el.dataset.date);return}const topics=state.topics.filter(t=>t.date===el.dataset.date);if(topics.length===1)openContentCard(topics[0].id);else if(topics.length>1)dayDetails(el.dataset.date);else toast('Drag a topic connector here, or click a topic connector then this date.')};el.oncontextmenu=e=>{e.preventDefault();const ids=state.topics.filter(t=>t.date===el.dataset.date).map(t=>t.id);context(e,ids.length?[['connect',`Disconnect ${ids.length===1?'topic':'all '+ids.length+' topics'}`,()=>{checkpoint();state.topics.forEach(t=>{if(ids.includes(t.id)){t.date=null;t.time=''}});save();renderStructure();beep('disconnect');toast('Publishing date cleared')}]]:[['calendar','This date is open',()=>toast('Connect a topic to start planning')]])}})}
function renderScheduleWires(point){if(tab!=='structure')return;const field=$('#topicField'),rect=$('#structureBody').getBoundingClientRect();let html='';for(const t of state.topics){if(!t.date||!inMonth(t.date))continue;const el=$(`[data-topic="${t.id}"]`),date=$(`[data-date="${t.date}"]`);if(!el||!date)continue;const er=el.getBoundingClientRect(),dr=date.getBoundingClientRect(),rail=$('#dateList').getBoundingClientRect();const a={x:er.right-rect.left,y:er.top-rect.top+er.height/2};const endY=Math.max(rail.top+8,Math.min(rail.bottom-8,dr.top+dr.height/2));const portRect=date.querySelector('.date-port').getBoundingClientRect(),b={x:portRect.left+portRect.width/2-rect.left,y:endY-rect.top};html+=`<path d="${curve(a,b)}" class="${selectedTopic===t.id?'active':''}" style="--wire-color:${validColor(t.color)}" data-wire-topic="${escapeHTML(t.id)}"/>`}
 if(scheduleConnect){const el=$(`[data-topic="${scheduleConnect.id}"]`);if(el){const er=el.getBoundingClientRect(),a={x:er.right-rect.left,y:er.top-rect.top+er.height/2},b=point?{x:point.x-rect.left,y:point.y-rect.top}:{x:a.x+120,y:a.y+45};html+=`<path d="${curve(a,b)}" class="pending"/>`}}$('#scheduleWires').innerHTML=html;$$('[data-wire-topic]').forEach(p=>{p.oncontextmenu=e=>{e.preventDefault();context(e,[['connect','Disconnect wire',()=>disconnectTopic(p.dataset.wireTopic)]])};p.onclick=()=>{selectedTopic=p.dataset.wireTopic;renderStructure()}})}
function startScheduleWire(id,e){if(scheduleConnect?.id===id){cancelConnections();return}scheduleConnect={id,startX:e.clientX,startY:e.clientY,moved:false};startWireHand(e,validColor(state.topics.find(t=>t.id===id)?.color));selectedTopic=id;$$('.topic-card').forEach(el=>el.classList.toggle('active',el.dataset.topic===id));$$('[data-port]').forEach(p=>p.classList.toggle('armed',p.dataset.port===id));document.body.classList.add('wiring');$$('.keyboard-connect').forEach(el=>el.remove());$('#structureBody').insertAdjacentHTML('beforeend','<div class="keyboard-connect">Choose a publishing day · Esc to cancel</div>');renderScheduleWires({x:e.clientX,y:e.clientY})}
function connectTopic(id,date){const t=state.topics.find(t=>t.id===id);if(!t)return;checkpoint();t.date=date;selectedTopic=id;releaseWireHand(true);cancelConnections();renderStructure();save();beep();requestAnimationFrame(()=>{const item=$(`[data-date="${date}"]`);item?.classList.add('just-connected');StudioFX.connected(date)});toast(`Connected to ${formatDate(date,{weekday:'long',month:'short',day:'numeric'})}. Looking good.`)}
function disconnectTopic(id){const t=state.topics.find(t=>t.id===id);if(!t?.date)return toast('This topic is already waiting for a date');checkpoint();t.date=null;t.time='';cancelConnections();renderAll();save();beep('disconnect');toast('Disconnected. Room for a new plan.')}
function scheduleEditor(id){const t=state.topics.find(t=>t.id===id);if(!t)return;showModal(`<div class="modal-header"><div><div class="eyebrow">GIVE THE IDEA ITS MOMENT</div><h2 id="modalTitle">A date with your audience.</h2><p>${escapeHTML(t.title)}</p></div>${closeButton()}</div><form id="scheduleForm"><div class="field-row"><label class="field"><span>Publishing date</span><input id="publishDate" type="date" required value="${escapeHTML(t.date||localDate(today))}"></label><label class="field"><span>Time · optional</span><input id="publishTime" type="time" value="${escapeHTML(t.time||'')}"></label></div><p class="field-help">Times follow this device’s local timezone (${escapeHTML(Intl.DateTimeFormat().resolvedOptions().timeZone)}). This is your plan; publishing stays in your hands.</p><label class="field"><span>Production status</span><select id="publishStatus">${['Idea','In progress','Ready','Published'].map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select></label><div class="modal-actions split"><button class="text-btn danger" type="button" id="disconnectSchedule">${icon('connect')}Disconnect</button><div class="right"><button class="secondary-btn" type="button" data-close>Cancel</button><button class="primary-btn">${icon('check')}Save schedule</button></div></div></form>`);$('#disconnectSchedule').onclick=()=>{closeModal();disconnectTopic(id)};$('#scheduleForm').onsubmit=e=>{e.preventDefault();checkpoint();t.date=$('#publishDate').value;t.time=$('#publishTime').value;t.status=$('#publishStatus').value;month=new Date(parseDate(t.date).getFullYear(),parseDate(t.date).getMonth(),1);closeModal();renderAll();save();beep();toast('Schedule saved. One step closer.')}}
function changeMonth(delta){month=new Date(month.getFullYear(),month.getMonth()+delta,1);if(tab==='structure'){renderDates();renderScheduleWires()}else renderOverview()}
function renderOverview(){ViewSession.remember();const scheduled=state.topics.filter(t=>inMonth(t.date)),unscheduled=state.topics.filter(t=>!t.date);$('#overviewMonth').textContent=monthLabel();$('#overviewStats').innerHTML=`<span>${scheduled.length} planned <span class="calendar-summary-dot">·</span> ${scheduled.filter(t=>t.status==='Published').length} posted</span>`;renderAgenda();$('#unscheduledShelf').innerHTML=unscheduled.length?`<div class="unscheduled-shelf"><h3>Unscheduled <span>${unscheduled.length}</span></h3><div class="shelf-items">${unscheduled.map(t=>`<button data-unscheduled="${escapeHTML(t.id)}">${icon('clock')}${escapeHTML(t.title)}${icon('arrow')}</button>`).join('')}</div></div>`:'';$$('[data-unscheduled]').forEach(b=>b.onclick=()=>{selectedTopic=b.dataset.unscheduled;switchTab('structure');const t=state.topics.find(t=>t.id===selectedTopic);topicPan={x:80-(t.x||0)*ContentCamera.zoom,y:150-(t.y||0)*ContentCamera.zoom};updateTopicPan();renderScheduleWires()})}
function renderAgenda(){CalendarUI.render()}
function openContentCard(id){const t=state.topics.find(t=>t.id===id);if(!t)return;selectedTopic=id;switchTab('structure');topicPan={x:80-(t.x||0)*ContentCamera.zoom,y:160-(t.y||0)*ContentCamera.zoom};updateTopicPan();renderScheduleWires()}
function chooseTopicForDate(date){showModal(`<div class="modal-header"><div><div class="eyebrow">ADD TO YOUR CALENDAR</div><h2 id="modalTitle">${formatDate(date,{weekday:'long',month:'short',day:'numeric'})}</h2><p>Choose a topic to schedule on this day.</p></div>${closeButton()}</div><div class="board-library">${state.topics.map(t=>`<button class="library-card" data-picktopic="${escapeHTML(t.id)}"><strong>${escapeHTML(t.title)}</strong><small>${t.date?formatDate(t.date):'Unscheduled'} · ${escapeHTML(t.platform)}</small></button>`).join('')||'<p class="muted">Create a topic from your whiteboard to get started.</p>'}</div>`,true);$$('[data-picktopic]').forEach(b=>b.onclick=()=>{const t=state.topics.find(t=>t.id===b.dataset.picktopic);checkpoint();t.date=date;save();closeModal();renderOverview();beep();toast('Topic added to your calendar')})}
function dayDetails(date){const topics=state.topics.filter(t=>t.date===date);showModal(`<div class="modal-header"><div><div class="eyebrow">ON THE LINEUP</div><h2 id="modalTitle">${formatDate(date,{weekday:'long',month:'short',day:'numeric'})}</h2><p>${topics.length} stories with a place in your day.</p></div>${closeButton()}</div><div class="board-library">${topics.map(t=>`<button class="library-card" data-daytopic="${escapeHTML(t.id)}"><strong>${escapeHTML(t.title)}</strong><small>${escapeHTML(t.platform)} · ${formatTime(t.time)}</small></button>`).join('')}</div>`);$$('[data-daytopic]').forEach(b=>b.onclick=()=>{const t=state.topics.find(t=>t.id===b.dataset.daytopic);closeModal();openBoard(t.boardId)})}
function boardLibrary(){Projects.open()}
function help(){const shortcuts=[['Copy / Cut','Ctrl C / X'],['Paste','Ctrl V'],['Undo','Ctrl Z'],['Redo','Ctrl Shift Z'],['Duplicate card','Ctrl D'],['Delete selection','Delete'],['Select all objects','Ctrl A'],['Box / Lasso selection','Shift / Ctrl Shift + drag'],['Cut wires','Right-drag or K'],['Select / Pan','V / H'],['Text / Note','T / N'],['Draw / Shape','P / S'],['Image / Reference','I / L'],['Fit board','0'],['Pan canvas','Hold Space'],['Zoom','Mouse wheel'],['Pan vertically','Shift + wheel'],['Cancel / Close','Esc']];showModal(`<div class="modal-header"><div><div class="eyebrow">A LITTLE GUIDANCE</div><h2 id="modalTitle">Make yourself at home.</h2><p>A workspace built around the way a story comes together.</p></div>${closeButton()}</div><div class="help-steps"><div><strong>01 · Collect</strong>Gather thoughts, images and references. Drag from a card’s edge to connect the ideas.</div><div><strong>02 · Connect</strong>Name your board to name its content. Drag its connector to a publishing day. Double-click content to revisit the research.</div><div><strong>03 · Create</strong>Track your shots and see the month’s lineup.</div></div><div class="shortcut-grid">${shortcuts.map(s=>`<div class="shortcut-row"><span>${s[0]}</span><kbd>${s[1]}</kbd></div>`).join('')}</div><div class="help-section"><strong>Make it a Windows app.</strong><br>In Chrome or Edge, use the address bar’s install icon, or the browser menu → Apps → Install this site as an app. Once installed, Sam’s Canvas opens in its own window and works offline.<br><button class="text-btn" id="installApp">${icon('download')}Install Sam’s Canvas</button></div><div class="help-section"><strong>Your work stays with you.</strong><br>This testing workspace opens without login. It saves on this browser/device. Export a backup to move it, or connect Supabase when you’re ready for account syncing.<br><button class="text-btn" id="helpCloud">${icon('connect')}Supabase setup</button><button class="text-btn" id="importWorkspace">${icon('folder')}Import backup</button></div>`,true);$('#installApp').onclick=installApp;$('#helpCloud').onclick=cloudSettings;$('#importWorkspace').onclick=()=>$('#importInput').click()}
async function installApp(){if(installPrompt){await installPrompt.prompt();const choice=await installPrompt.userChoice;installPrompt=null;if(choice.outcome==='accepted')toast('Sam’s Canvas has a new home on your desktop.')}else toast('Use Edge or Chrome → menu → Apps → Install Sam’s Canvas. Installation needs localhost or HTTPS.')}
function updateSound(){$('#soundButton').innerHTML=icon(state.sound?'sound':'mute');$('#soundButton').title=state.sound?'Connection sounds on':'Connection sounds off';$('#soundButton').setAttribute('aria-pressed',String(state.sound))}
function download(content,name,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function exportBackup(){download(JSON.stringify(state,null,2),`threadline-backup-${localDate()}.json`);toast('Workspace backed up. Ideas included.')}
function exportICS(){const topics=state.topics.filter(t=>t.date);if(!topics.length)return toast('Schedule a topic first to export your calendar');const esc=v=>String(v||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Sam’s Canvas//Creator Studio//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH'];for(const t of topics){lines.push('BEGIN:VEVENT',`UID:${t.id}@threadline`,`DTSTAMP:${stamp}`);if(t.time){const d=parseDate(t.date),[h,m]=t.time.split(':').map(Number);d.setHours(h,m,0,0);const start=d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');lines.push(`DTSTART:${start}`,`DTEND:${new Date(d.getTime()+1800000).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`)}else{const d=parseDate(t.date);d.setDate(d.getDate()+1);lines.push(`DTSTART;VALUE=DATE:${t.date.replaceAll('-','')}`,`DTEND;VALUE=DATE:${localDate(d).replaceAll('-','')}`)}lines.push(`SUMMARY:${esc(t.title)}`,`DESCRIPTION:${esc(t.platform+' · '+t.format+'\n'+t.summary+'\n\n'+t.pointers.map((p,i)=>(i+1)+'. '+p).join('\n'))}`,'END:VEVENT')}lines.push('END:VCALENDAR');const folded=lines.map(line=>{const chunks=[];let chunk='',count=0;for(const char of line){const bytes=new TextEncoder().encode(char).length;if(count+bytes>73){chunks.push(chunk);chunk=' '+char;count=1+bytes}else{chunk+=char;count+=bytes}}chunks.push(chunk);return chunks.join('\r\n')}).join('\r\n')+'\r\n';download(folded,'threadline-content-calendar.ics','text/calendar');toast('Calendar exported. Your lineup, wherever you need it.')}
