$('#canvas').onpointerdown=e=>{if(e.target.closest('.canvas-bottom,.tool-options,.node,#selectionActions'))return;if(e.button===2){if(tool==='note'){e.preventDefault();CanvasSelection.suppressContextUntil=Date.now()+350;setTool('select')}else CanvasSelection.rightStart(e,'board');return}if(e.button!==0)return;CanvasSelection.focusCanvas();if(tool==='stamp'){e.preventDefault();StampKit.place(scenePoint(e),e);return}if(tool==='note'){e.preventDefault();CanvasEditor.placeSticky(scenePoint(e));return}if(tool==='select'&&e.shiftKey){CanvasSelection.start(e,e.ctrlKey||e.metaKey?'lasso':'rectangle');return}if(tool==='cut'){startWireCut(e,'board');return}if(boardConnect)cancelConnections();if(tool==='hand'||spacePressed){selectNode(null);startPan(e);return}if(tool==='pen'){e.preventDefault();checkpoint();const p=scenePoint(e),stroke={points:[[p.x,p.y]],color:inkColor,size:inkSize};board().strokes.push(stroke);drag={type:'ink',stroke};$('#canvas').setPointerCapture?.(e.pointerId);renderInk();return}if(tool==='shape'){startShapeDraw(e);return}if(tool==='text'){e.preventDefault();CanvasEditor.createText(scenePoint(e));return}selectNode(null);startPan(e)};
$('#canvas').oncontextmenu=e=>CanvasSelection.context(e);

document.addEventListener('pointermove',e=>{
 if(drag?.type==='selection'){CanvasSelection.move(e);return}
 if(drag?.type==='rightPending'){const d=drag;if(Math.hypot(e.clientX-d.startX,e.clientY-d.startY)>4){CanvasSelection.suppressContextUntil=Date.now()+600;startWireCut(d.original,d.kind);updateWireCut(e)}return}
 if(boardConnect){if(e.buttons)boardConnect.moved=true;WireMagnet.sense(e);followWire(scenePoint(e));moveWireHand(e.clientX,e.clientY)}
 if(scheduleConnect){if(e.buttons&&Math.hypot(e.clientX-scheduleConnect.startX,e.clientY-scheduleConnect.startY)>5)scheduleConnect.moved=true;followWire({x:e.clientX,y:e.clientY});moveWireHand(e.clientX,e.clientY);$$('.date-item.drop-target').forEach(d=>d.classList.remove('drop-target'));document.elementFromPoint(e.clientX,e.clientY)?.closest('.date-item')?.classList.add('drop-target');const rail=$('#dateList').getBoundingClientRect();if(e.clientX>rail.left&&e.clientX<rail.right){if(e.clientY>rail.bottom-38)$('#dateList').scrollTop+=12;else if(e.clientY<rail.top+38)$('#dateList').scrollTop-=12}}
 if(!drag)return;if(drag.type==='wireCut'){updateWireCut(e);return}const dx=e.clientX-drag.startX,dy=e.clientY-drag.startY;
 if(drag.type==='node'){drag.targetX=drag.x+dx/zoom;drag.targetY=drag.y+dy/zoom;drag.moved=true;followDrag(drag)}
 if(drag.type==='transform')updateNodeTransform(e);
 if(drag.type==='pan'){drag.targetX=drag.x+dx;drag.targetY=drag.y+dy;followDrag(drag)}
 if(drag.type==='topicPan'){drag.targetX=drag.x+dx;drag.targetY=drag.y+dy;followDrag(drag)}
 if(drag.type==='shapeDraw'){updateShapeDraw(e)}
 if(drag.type==='ink'){const p=scenePoint(e);drag.stroke.points.push([Math.round(p.x*10)/10,Math.round(p.y*10)/10]);renderInk()}
 if(drag.type==='topic'){const el=$(`[data-topic="${drag.topic.id}"]`);drag.targetX=drag.x+dx/ContentCamera.zoom;drag.targetY=drag.y+dy/ContentCamera.zoom;drag.moved=Math.hypot(dx,dy)>3;followDrag(drag)}
});
document.addEventListener('pointerup',e=>{
 if(drag?.type==='selection'){CanvasSelection.finish();return}
 if(drag?.type==='rightPending'){drag=null;return}
 if(drag?.type==='wireCut')CanvasSelection.suppressContextUntil=Date.now()+500;
 if(boardConnect?.moved&&WireMagnet.target){finishBoardWire(WireMagnet.target.id,WireMagnet.target.side)}else if(boardConnect?.moved){cancelConnections()}
 if(scheduleConnect?.moved){const date=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-date]');if(date)connectTopic(scheduleConnect.id,date.dataset.date);else cancelConnections()}
 $$('.date-item.drop-target').forEach(d=>d.classList.remove('drop-target'));
 if(!drag)return;if(drag.type==='wireCut')finishWireCut(drag);if(drag.type==='shapeDraw')finishShapeDraw(drag);const previous=drag;previous.released=true;drag=null;$$('.dragging').forEach(el=>el.classList.remove('dragging'));$('#canvas').classList.remove('panning');if(previous.type==='topic'&&!previous.moved){history.pop();updateHistory()}else if(previous.type==='node'&&!previous.moved){history.pop();updateHistory()}else if(!['pan','topicPan'].includes(previous.type))save();
});
document.addEventListener('pointercancel',()=>{if(drag?.type==='selection')CanvasSelection.finish();if(drag?.type==='shapeDraw')finishShapeDraw(drag);drag=null;cancelConnections();$('#canvas').classList.remove('panning');renderNodes();renderInk();save()});
$('#canvas').addEventListener('wheel',e=>{if(e.target.closest('.tool-options,.canvas-bottom'))return;e.preventDefault();if(e.shiftKey){const base=cameraFrame?cameraTarget:{x:pan.x,y:pan.y,z:zoom};moveCamera(base.x,base.y-(e.deltaY||e.deltaX),base.z)}else zoomBy(Math.exp(-e.deltaY*.0018),{x:e.clientX,y:e.clientY})},{passive:false});
$('#canvas').ondragover=e=>{e.preventDefault();if(!$('.image-drop-hint'))$('#canvas').insertAdjacentHTML('beforeend','<div class="image-drop-hint">Drop a little inspiration here.</div>')};$('#canvas').ondragleave=e=>{if(!$('#canvas').contains(e.relatedTarget))$('.image-drop-hint')?.remove()};$('#canvas').ondrop=e=>{e.preventDefault();$('.image-drop-hint')?.remove();const point=scenePoint(e);[...e.dataTransfer.files].filter(f=>f.type.startsWith('image/')).forEach((f,i)=>addImage(f,{x:point.x+30*i,y:point.y+30*i}));if(!e.dataTransfer.files.length){const text=e.dataTransfer.getData('text/plain');if(safeURL(text))openReference(text);else if(text)addNode('text',point,{title:'A collected thought',text})}};
$('#imageInput').onchange=e=>{[...e.target.files].forEach(f=>addImage(f));e.target.value=''};
document.addEventListener('copy',e=>{if(tab==='whiteboard'&&!isEditing()&&(CanvasSelection.ids.size>1||InkSelection.hasSelected())){CanvasSelection.copy(e,false);return}if(tab!=='whiteboard'||!selectedNode||isEditing())return;const node=board().nodes.find(n=>n.id===selectedNode);if(!node)return;clipboard=clone(node);e.clipboardData.setData('application/x-threadline',JSON.stringify(node));e.clipboardData.setData('text/plain',node.title+(node.text?'\n'+node.text:''));e.preventDefault();toast('Card copied')});
document.addEventListener('cut',e=>{if(tab==='whiteboard'&&!isEditing()&&(CanvasSelection.ids.size>1||InkSelection.hasSelected())){CanvasSelection.copy(e,true);return}if(tab!=='whiteboard'||!selectedNode||isEditing())return;const node=board().nodes.find(n=>n.id===selectedNode);if(!node)return;clipboard=clone(node);e.clipboardData.setData('application/x-threadline',JSON.stringify(node));e.clipboardData.setData('text/plain',node.title||'');e.preventDefault();removeNode(selectedNode)});
document.addEventListener('paste',e=>{if(tab!=='whiteboard'||isEditing())return;const raw=e.clipboardData.getData('application/x-threadline');if(raw){try{const n=JSON.parse(raw);if(n.kind==='selection'){e.preventDefault();CanvasSelection.paste(n);return}if(n.type==='sequencer'){e.preventDefault();CanvasEditor.createSequencer();return}if(!['text','note','sticky','image','video','link','shape','table','sequencer','stamp'].includes(n.type))throw Error();e.preventDefault();checkpoint();n.id=uid();n.x+=35;n.y+=35;board().nodes.push(n);CanvasSelection.one(n.id);renderNodes();save();return}catch{}}const image=[...e.clipboardData.items].find(i=>i.type.startsWith('image/'));if(image){e.preventDefault();addImage(image.getAsFile());return}const text=e.clipboardData.getData('text/plain');if(text){e.preventDefault();if(safeURL(text.trim()))openReference(text.trim());else addNode('text',null,{title:'A collected thought',text})}});
function isEditing(){const active=document.activeElement;return !$('#modalBackdrop').classList.contains('hidden')||active?.matches('input,textarea,select')||!!active?.closest('[contenteditable="true"],[contenteditable="plaintext-only"]')}
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'){if(tab==='whiteboard'&&['text','shape','cut','note','stamp'].includes(tool))setTool('select');CanvasSelection.one(null);closeModal();$('#contextMenu').classList.add('hidden');cancelConnections();selectedNode=null;$$('.node.selected').forEach(el=>el.classList.remove('selected'));renderToolOptions();return}
 if(!$('#modalBackdrop').classList.contains('hidden')){if(e.key==='Tab'){const els=$$('button,a[href],input,textarea,select,[tabindex="0"]',$('#modal')).filter(el=>!el.disabled&&!el.hidden);if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0]?.focus()}}return}
 if(isEditing())return;const ctrl=e.ctrlKey||e.metaKey;
 if(ctrl&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return}if(ctrl&&e.key.toLowerCase()==='y'){e.preventDefault();redo();return}
 if(tab==='whiteboard'){
 if(ctrl&&e.key.toLowerCase()==='d'){e.preventDefault();if(selectedNode)duplicateNode(selectedNode);return}
 if(ctrl&&e.key.toLowerCase()==='s'){e.preventDefault();save();toast('Workspace saved on this device');return}
 if(ctrl)return;if(['Delete','Backspace'].includes(e.key)&&selectedNode){e.preventDefault();removeNode(selectedNode);return}
 if(e.code==='Space'){e.preventDefault();spacePressed=true;$('#canvas').classList.add('tool-hand');return}
 if(e.key==='0'){e.preventDefault();fitBoard();return}if(e.key==='+'||e.key==='='){zoomBy(1.15);return}if(e.key==='-'){zoomBy(1/1.15);return}
 const shortcuts={v:'select',h:'hand',t:'text',n:'note',p:'pen',s:'shape',i:'image',l:'link',k:'cut'};if(shortcuts[e.key.toLowerCase()]){e.preventDefault();setTool(shortcuts[e.key.toLowerCase()])}
 if(selectedNode&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();checkpoint();const n=board().nodes.find(n=>n.id===selectedNode),step=e.shiftKey?20:5;n.x+=(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0);n.y+=(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0);renderNodes();save()}
 }
});
