$$('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));$('#newBoard').onclick=createBoard;$('#newBoardSide').onclick=createBoard;$('#allBoards').onclick=boardLibrary;$('#allTopics').onclick=()=>switchTab('structure');$('#workspaceButton').onclick=cloudSettings;$('#profileButton').onclick=cloudSettings;$('#boardTitleButton').onclick=()=>renameBoard(board().id);$('#helpButton').onclick=help;$('#backupButton').onclick=exportBackup;$('#soundButton').onclick=()=>{state.sound=!state.sound;updateSound();save();if(state.sound)beep();toast(state.sound?'A little sound, a little satisfaction.':'Connection sounds off')};$('#boardMenu').onclick=e=>Projects.options(e);$('#undoButton').onclick=undo;$('#redoButton').onclick=redo;$('#zoomIn').onclick=()=>zoomBy(1.15);$('#zoomOut').onclick=()=>zoomBy(1/1.15);$('#fitBoard').onclick=fitBoard;$('#newTopicButton').onclick=createBoard;$('#prevMonth').onclick=()=>changeMonth(-1);$('#nextMonth').onclick=()=>changeMonth(1);$('#overviewPrev').onclick=()=>changeMonth(-1);$('#overviewNext').onclick=()=>changeMonth(1);$('#jumpToday').onclick=()=>{month=currentMonth();renderDates();renderScheduleWires();$(`[data-date="${localDate(today)}"]`)?.scrollIntoView({block:'center',behavior:'smooth'})};$('#exportCalendar').onclick=exportICS;$('#agendaSearch').oninput=renderAgenda;$('#dateList').onscroll=()=>{if(ContentCamera.scrollFrame)return;ContentCamera.scrollFrame=requestAnimationFrame(()=>{ContentCamera.scrollFrame=0;renderScheduleWires()})};$('#topicField').onscroll=()=>renderScheduleWires();
$('#importInput').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>30*1024*1024)return toast('This backup is too large. Choose a file under 30 MB.');try{const imported=JSON.parse(await file.text());if(!validWorkspace(imported))throw Error();showModal(`<div class="modal-header"><div><div class="eyebrow">A FAMILIAR SET OF IDEAS</div><h2 id="modalTitle">Open this workspace backup?</h2><p>Replace this workspace with ${imported.boards.length} research boards and ${imported.topics.length} topics from “${escapeHTML(file.name)}”. Export your current workspace first if you want to keep both. You can undo the import.</p></div>${closeButton()}</div><div class="modal-actions"><button class="secondary-btn" id="backupBeforeImport">Export current backup</button><button class="primary-btn" id="confirmImport">Open backup</button></div>`);$('#backupBeforeImport').onclick=exportBackup;$('#confirmImport').onclick=()=>{checkpoint();state=imported;if(!state.boards.some(b=>b.id===state.activeBoard))state.activeBoard=state.boards[0].id;selectedNode=null;selectedTopic=null;closeModal();renderAll();fitBoard();save();toast('Workspace restored. Welcome back to your ideas.')}}catch{toast('This is not a valid Sam’s Canvas workspace backup. Your current work is safe.')}};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});window.addEventListener('resize',()=>{updateTabs();if(tab==='structure')renderStructure();else if(tab==='whiteboard')fitBoard()});
