// Optional Supabase sync. No account is required to use the testing workspace.
function cloudSettings(){showModal(`<div class="modal-header"><div><div class="eyebrow">YOUR STUDIO, WHEREVER YOU ARE</div><h2 id="modalTitle">Local now. Connected when ready.</h2><p>The testing workspace opens freely. Connect your own Supabase project when you’re ready to sync accounts.</p></div>${closeButton()}</div><form id="cloudConfigForm"><label class="field"><span>Supabase project URL</span><input type="url" id="supabaseURL" placeholder="https://your-project.supabase.co" value="${escapeHTML(cloudConfig?.url||'')}" required></label><label class="field"><span>Public publishable key</span><input id="supabaseKey" placeholder="sb_publishable_…" value="${escapeHTML(cloudConfig?.key||'')}" required></label><p class="field-help">Run the included supabase/schema.sql in your project first. Use a publishable key or legacy anon key. Never use a secret or service-role key. This configuration stays on your device.</p><div class="modal-actions"><button class="secondary-btn" type="button" data-close>Keep testing locally</button><button class="primary-btn">${icon('check')}Save connection</button></div></form><div class="help-section">${cloudSession?`<strong>Signed in as ${escapeHTML(cloudSession.user?.email||'your account')}</strong><br><span id="cloudMessage">${cloudReady?'Sync ready.':'Choose a workspace to begin syncing.'}</span><br><button class="text-btn" id="syncNow">${icon('connect')}Sync workspace</button><button class="text-btn" id="signOut">Sign out</button>`:`<strong>Login is optional.</strong><br>When your database is ready, sign in with an email code to sync this workspace.<form id="cloudLoginForm"><label class="field" style="margin-top:12px"><span>Email address</span><input type="email" id="cloudEmail" required placeholder="you@yourstudio.com"></label><button class="secondary-btn">Send sign-in code</button></form>`}</div>`,true);$('#cloudConfigForm').onsubmit=e=>{e.preventDefault();let url;try{const u=new URL($('#supabaseURL').value);if(u.protocol!=='https:'||!u.hostname.endsWith('.supabase.co')||u.pathname!=='/')throw Error();url=u.origin}catch{return toast('Use your HTTPS project URL from Supabase, ending in .supabase.co')};const key=$('#supabaseKey').value.trim();let secret=key.startsWith('sb_secret_');try{const p=JSON.parse(atob(key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));secret=secret||p.role==='service_role'}catch{}if(secret)return toast('Use a public publishable or anon key. Secret keys do not belong in this app.');if(!key.startsWith('sb_publishable_')&&!key.startsWith('eyJ'))return toast('Enter your public Supabase publishable or legacy anon key');const changed=cloudConfig?.url!==url;cloudConfig={url,key};localStorage.setItem('threadline.cloud.config',JSON.stringify(cloudConfig));if(changed){cloudSession=null;cloudReady=false;localStorage.removeItem('threadline.cloud.session')}toast('Connection saved. Local testing stays open.');cloudSettings()};if($('#cloudLoginForm'))$('#cloudLoginForm').onsubmit=async e=>{e.preventDefault();if(!cloudConfig)return toast('Save your project URL and public key first');const email=$('#cloudEmail').value.trim(),button=$('#cloudLoginForm button');button.disabled=true;button.textContent='Sending…';try{await sb('/auth/v1/otp',{method:'POST',body:{email,create_user:true}});otpDialog(email)}catch(err){toast(err.message);button.disabled=false;button.textContent='Send sign-in code'}};if($('#syncNow'))$('#syncNow').onclick=()=>cloudReady?syncCloud(true):startCloud();if($('#signOut'))$('#signOut').onclick=async()=>{try{await sb('/auth/v1/logout',{method:'POST'},true)}catch{}cloudSession=null;cloudReady=false;cloudVersion=null;localStorage.removeItem('threadline.cloud.session');cloudSettings();toast('Signed out. Your local workspace is still here.')}}
async function sb(path,options={},auth=false){if(!cloudConfig)throw Error('Save a Supabase connection first');if(auth&&cloudSession&&cloudSession.expires_at<Date.now()/1000+60)await refreshSession();const headers={apikey:cloudConfig.key,'Content-Type':'application/json',...(auth&&cloudSession?{Authorization:'Bearer '+cloudSession.access_token}:{}),...options.headers};const response=await fetch(cloudConfig.url+path,{...options,headers,body:options.body?JSON.stringify(options.body):undefined,signal:AbortSignal.timeout(18000)});if(!response.ok){let data;try{data=await response.json()}catch{}throw Error(data?.msg||data?.message||data?.error_description||'Supabase could not complete the request ('+response.status+').')}return response.status===204?null:response.text().then(t=>t?JSON.parse(t):null)}
async function refreshSession(){if(!cloudSession?.refresh_token)throw Error('Sign in again to continue syncing');const result=await sb('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:{refresh_token:cloudSession.refresh_token}});cloudSession={...result,expires_at:Date.now()/1000+result.expires_in};localStorage.setItem('threadline.cloud.session',JSON.stringify(cloudSession))}
function otpDialog(email){showModal(`<div class="modal-header"><div><div class="eyebrow">CHECK YOUR INBOX</div><h2 id="modalTitle">Your studio is one code away.</h2><p>Enter the sign-in code sent to ${escapeHTML(email)}. Supabase’s email template must include the Token variable, as described in the setup guide.</p></div>${closeButton()}</div><form id="otpForm"><label class="field"><span>Email sign-in code</span><input id="otpCode" inputmode="numeric" autocomplete="one-time-code" minlength="6" maxlength="10" required placeholder="Your code"></label><div class="modal-actions"><button type="button" class="secondary-btn" data-close>Keep testing locally</button><button class="primary-btn">Sign in</button></div></form>`);$('#otpForm').onsubmit=async e=>{e.preventDefault();const button=$('#otpForm .primary-btn');button.disabled=true;try{const result=await sb('/auth/v1/verify',{method:'POST',body:{email,token:$('#otpCode').value.trim(),type:'email'}});cloudSession={...result,expires_at:Date.now()/1000+result.expires_in};localStorage.setItem('threadline.cloud.session',JSON.stringify(cloudSession));await startCloud()}catch(err){toast(err.message);button.disabled=false}}}
async function startCloud(){if(!cloudSession)return cloudSettings();try{const rows=await sb('/rest/v1/creator_workspaces?select=payload,revision,updated_at&user_id=eq.'+encodeURIComponent(cloudSession.user.id),{},true);const remote=rows?.[0];if(remote){if(!validWorkspace(remote.payload))throw Error('The cloud workspace could not be read. Export a local backup before continuing.');showModal(`<div class="modal-header"><div><div class="eyebrow">TWO PLACES, ONE CREATIVE SPACE</div><h2 id="modalTitle">Which workspace should we keep?</h2><p>Your cloud account already has a workspace. Pick the starting point for syncing. Export a backup first if you’d like to keep a separate copy.</p></div>${closeButton()}</div><div class="board-library"><button class="library-card" id="useCloud"><strong>Open cloud workspace</strong><small>${remote.payload.boards.length} boards · ${remote.payload.topics.length} topics</small></button><button class="library-card" id="useLocal"><strong>Upload this device’s workspace</strong><small>${state.boards.length} boards · ${state.topics.length} topics</small></button></div><div class="modal-actions"><button class="secondary-btn" id="cloudBackup">Export device backup</button><button class="secondary-btn" data-close>Decide later</button></div>`);$('#cloudBackup').onclick=exportBackup;$('#useCloud').onclick=()=>{checkpoint();state=clone(remote.payload);cloudVersion=remote.revision;cloudReady=true;cloudConflict=false;closeModal();renderAll();fitBoard();try{localStorage.setItem(STORE,JSON.stringify(state))}catch{}toast('Cloud workspace opened. Sync is ready.')};$('#useLocal').onclick=async()=>{cloudVersion=remote.revision;cloudReady=true;cloudConflict=false;closeModal();await syncCloud(true)}}else{cloudVersion=null;cloudReady=true;cloudConflict=false;await syncCloud(true);closeModal()}}catch(err){cloudReady=false;toast(err.message)}}
async function syncCloud(manual=false){if(!cloudReady||!cloudSession||cloudBusy||cloudConflict)return;cloudBusy=true;const revision=uid(),snapshot=clone(state),version=cloudVersion;try{let rows;if(version===null){rows=await sb('/rest/v1/creator_workspaces',{method:'POST',headers:{Prefer:'return=representation'},body:{user_id:cloudSession.user.id,payload:snapshot,revision}},true)}else{rows=await sb('/rest/v1/creator_workspaces?user_id=eq.'+encodeURIComponent(cloudSession.user.id)+'&revision=eq.'+encodeURIComponent(version),{method:'PATCH',headers:{Prefer:'return=representation'},body:{payload:snapshot,revision}},true)}if(!rows?.length){cloudConflict=true;cloudReady=false;throw Error('Cloud work changed on another device. Open My studio → Sync workspace to choose which version to keep.')}cloudVersion=revision;if(manual)toast('Workspace synced. Your ideas can travel now.');if(state.updatedAt!==snapshot.updatedAt){clearTimeout(cloudTimer);cloudTimer=setTimeout(()=>syncCloud(),1000)}}catch(err){if(manual||cloudConflict)toast(err.message);else{$('#saveState').textContent='Saved locally · cloud sync needs attention';cloudReady=false}}finally{cloudBusy=false}}
window.addEventListener('online',()=>{if(cloudReady)syncCloud()});
function sequences(){if(!Array.isArray(state.sequences))state.sequences=[];return state.sequences}
function activeSequence(contentId){const content=state.topics.find(t=>t.id===contentId);const seq=content?CanvasEditor.sequenceForBoard(content.boardId):null;return seq&&!seq.archived?seq:undefined}
function newSequence(content){return CanvasEditor.ensureSequence(content,false)}
function makeShot(notes=''){return{id:uid(),notes,done:false,completedAt:null}}
function celebrateWrap(){if(reduceMotion())return;$('.wrap-confetti')?.remove();const colors=['#0d99ff','#38a9ff','#b5b5c0','#747480'];document.body.insertAdjacentHTML('beforeend',`<div class="wrap-confetti" aria-hidden="true">${Array.from({length:20},(_,i)=>`<span style="--dx:${(i-10)*26}px;--dy:${60+(i%5)*24}px;--spin:${i*37}deg;--delay:${i%4*25}ms;background:${colors[i%colors.length]}"></span>`).join('')}</div>`);setTimeout(()=>$('.wrap-confetti')?.remove(),1400)}
function stampHTML(done){return done?`<span class="recorded-stamp">${icon('check')}RECORDED</span>`:`<span class="empty-stamp">${icon('stamp')}<span>STAMP RECORDED</span><small>Click when you’ve got the shot</small></span>`}
function renderShots(){
 ViewSession.remember();
 const shell=$('#shotsShell'),content=state.topics.find(t=>t.id===shotContentId)||state.topics[0];if(content){shotContentId=content.id;state.activeBoard=content.boardId;syncProjectTitle()}
 const archived=sequences().filter(s=>s.archived).sort((a,b)=>(b.completedAt||'').localeCompare(a.completedAt||''));
 const header=`<div class="shots-top"><div class="shots-content-picker"><span class="shots-overline">CONTENT</span><button id="shotContentSelect" class="content-picker-trigger" role="combobox" aria-expanded="false" aria-haspopup="listbox" aria-controls="contentPickerList" aria-label="Choose content for the shot sequencer" title="${escapeHTML(content?.title||'Choose content')}"><span>${escapeHTML(content?.title||'Choose content')}</span>${icon('down')}</button><div id="contentPickerMenu" class="content-picker-menu hidden"><label class="content-picker-search">${icon('search')}<input id="contentPickerSearch" placeholder="Find your content…" autocomplete="off" aria-label="Search content"></label><div id="contentPickerList" role="listbox" aria-label="Your content"></div><div class="content-picker-footer">Choose a story. Plan the shots.</div></div></div><div class="shots-top-actions"><div class="shots-mode-tabs"><button data-shotmode="active" class="${shotMode==='active'?'selected':''}">${icon('sequence')}Shot list</button><button data-shotmode="history" class="${shotMode==='history'?'selected':''}">${icon('history')}History <span>${archived.length}</span></button></div></div></div>`;
 shell.innerHTML=header+`<div id="shotsBody" class="shots-body"></div>`;
 $('#shotContentSelect').onclick=toggleContentPicker;$('#shotContentSelect').onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();toggleContentPicker(true)}};$('#contentPickerSearch').oninput=renderContentPickerOptions;$('#contentPickerSearch').onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();$('[data-content-choice]')?.focus()}if(e.key==='Enter')$('[data-content-choice]')?.click()};$$('[data-shotmode]').forEach(b=>b.onclick=()=>{shotMode=b.dataset.shotmode;shotHistoryId=null;renderShots()});
 if(shotMode==='history'){
  const selected=archived.find(s=>s.id===shotHistoryId);
  if(selected){renderShotSheet(selected,true);return}
  $('#shotsBody').innerHTML=`<div class="shot-history-heading"><h2>Recorded. Remembered.</h2><p>Every finished shot list, saved here when the last take is done.</p></div>${archived.length?`<div class="shot-history-grid">${archived.map(s=>`<button class="shot-history-card" data-history-sequence="${escapeHTML(s.id)}"><div class="history-card-top">${icon('sequence')}<span>COMPLETED</span>${icon('arrow')}</div><h3>${escapeHTML(s.contentTitle)}</h3><div class="history-card-meta"><span>${s.shots.length} shots recorded</span><span>${new Date(s.completedAt).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</span></div><span class="mini-stamp">${icon('check')}ALL SHOTS RECORDED</span></button>`).join('')}</div>`:`<div class="empty-state">${icon('history')}<h3>Your finished shot lists will live here.</h3><p>Record every shot in a sequence and we’ll save it to History automatically.</p></div>`}`;
  $$('[data-history-sequence]').forEach(b=>b.onclick=()=>{shotHistoryId=b.dataset.historySequence;renderShots()});return;
 }
 if(!content){$('#shotsBody').innerHTML=`<div class="empty-state">${icon('sequence')}<h3>A shot list starts with a piece of content.</h3><p>Save your research board as content, then plan what you’ll record.</p><button class="primary-btn" id="shotsCreateContent">${icon('plus')}Create content</button></div>`;$('#shotsCreateContent').onclick=()=>topicEditor(null,board().id);return}
 const seq=activeSequence(content.id);
 if(!seq){const finished=archived.filter(s=>s.contentId===content.id);$('#shotsBody').innerHTML=`<div class="shot-start"><span class="shot-start-icon">${icon('sequence')}</span><h2>${finished.length?'The shots are in. What’s next?':'One story. One shot at a time.'}</h2><p>${finished.length?'Your finished sequence is in History. Reopen the same shot list whenever you need another take.':'Break this piece of content into the moments you want to capture.'}</p><div><button class="primary-btn" id="startShotList">${icon('plus')}${finished.length?'Reopen shot list':'Create shot list'}</button>${finished.length?'<button class="secondary-btn" id="showFinishedSequence">Open completed sequence</button>':''}</div><small>${content.pointers.length?'We’ll use your talking points as a starting point. You can rewrite every shot.':'Start with a blank shot and build your sequence.'}</small></div>`;$('#startShotList').onclick=()=>CanvasEditor.startSequence(content);if($('#showFinishedSequence'))$('#showFinishedSequence').onclick=()=>{shotMode='history';shotHistoryId=finished[0].id;renderShots()};return}
 renderShotSheet(seq,false);
}
function toggleContentPicker(force){const menu=$('#contentPickerMenu');if(!menu)return;const open=force===true||menu.classList.contains('hidden')||!menu.classList.contains('is-open');if(!open){closeContentPicker();return}menu.classList.remove('hidden');$('#shotContentSelect').setAttribute('aria-expanded','true');$('#shotContentSelect').classList.add('open');$('#contentPickerSearch').value='';renderContentPickerOptions();requestAnimationFrame(()=>{menu.classList.add('is-open');$('#contentPickerSearch')?.focus({preventScroll:true})})}
function closeContentPicker(){const menu=$('#contentPickerMenu');if(!menu)return;menu.classList.remove('is-open');$('#shotContentSelect')?.setAttribute('aria-expanded','false');$('#shotContentSelect')?.classList.remove('open');setTimeout(()=>{if(menu.isConnected&&!menu.classList.contains('is-open'))menu.classList.add('hidden')},160)}
function renderContentPickerOptions(){const query=($('#contentPickerSearch')?.value||'').toLowerCase(),items=state.topics.filter(t=>`${t.title} ${t.platform} ${t.format}`.toLowerCase().includes(query)),list=$('#contentPickerList');if(!list)return;list.innerHTML=items.map(t=>{const seq=activeSequence(t.id),done=seq?.shots.filter(s=>s.done).length||0;return `<button class="content-picker-option ${t.id===shotContentId?'selected':''}" data-content-choice="${escapeHTML(t.id)}" role="option" aria-selected="${t.id===shotContentId}"><span class="picker-content-icon">${icon('clapper')}</span><span class="picker-content-copy"><strong>${escapeHTML(t.title)}</strong><small>${escapeHTML(t.format)} · ${seq?`${done} / ${seq.shots.length} shots recorded`:'No active shot list'}</small></span>${t.id===shotContentId?icon('check'):''}</button>`}).join('')||'<div class="picker-no-results">No content found. Try another title.</div>';$$('[data-content-choice]').forEach((b,i)=>{b.onclick=()=>{shotContentId=b.dataset.contentChoice;shotMode='active';shotHistoryId=null;renderShots()};b.onkeydown=e=>{const options=$$('[data-content-choice]');if(e.key==='ArrowDown'){e.preventDefault();options[(i+1)%options.length]?.focus()}else if(e.key==='ArrowUp'){e.preventDefault();options[(i-1+options.length)%options.length]?.focus()}}})}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.shots-content-picker'))closeContentPicker()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#contentPickerMenu')?.classList.contains('is-open')){closeContentPicker();$('#shotContentSelect')?.focus({preventScroll:true})}});
function renderShotSheet(seq,readOnly){
 const done=seq.shots.filter(s=>s.done).length,total=seq.shots.length;
 $('#shotsBody').innerHTML=`<div class="shot-sheet-top"><div class="shot-launch"><span class="shot-slate">${icon('clapper')}<i>Action!</i></span><div><span class="shot-desk-label"><b></b>${readOnly?'THAT’S A WRAP':'YOUR PRODUCTION DESK'}</span><h2>${readOnly?'The story is in the can.':'Lights. Camera. Your story.'}</h2><p>${readOnly?'Every moment captured, every detail remembered.':'A little focus. A good take. One shot closer.'}</p></div></div><div class="shot-progress"><span>${readOnly?'COMPLETED SEQUENCE':'RECORDING PROGRESS'}</span><strong>${done}<span> / ${total} shots</span></strong><div class="shot-progress-track"><span style="width:${total?done/total*100:0}%"></span></div></div><div class="shot-sheet-actions">${readOnly?`<button class="text-btn" id="backShotHistory">${icon('history')}Back to history</button><button class="secondary-btn" id="reopenShotSequence">${icon('undo')}Reopen sequence</button>`:`<button class="secondary-btn" id="embedShotSequence">${icon('board')}Show on whiteboard</button><button class="primary-btn" id="addShotRow">${icon('plus')}Add shot</button>`}</div></div>${readOnly?`<div class="completed-sequence-title"><h2>${escapeHTML(seq.contentTitle)}</h2><span>Recorded ${new Date(seq.completedAt).toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}</span></div>`:''}<div class="shot-table" role="table" aria-label="Ordered shots"><div class="shot-table-head" role="row"><span>SHOT</span><span>SCRIPT & ACTION</span><span>RECORDING STAMP</span><span></span></div><div class="shot-rows">${seq.shots.map((shot,i)=>`<div class="shot-row ${shot.done?'is-recorded':''}" role="row"><div class="shot-number"><span>${String(i+1).padStart(2,'0')}</span><small>TAKE</small>${!readOnly?`<div class="shot-reorder"><button class="icon-btn small" data-move-shot="${shot.id}" data-direction="-1" ${i===0?'disabled':''} title="Move shot up" aria-label="Move shot ${i+1} up">${icon('up')}</button><button class="icon-btn small" data-move-shot="${shot.id}" data-direction="1" ${i===total-1?'disabled':''} title="Move shot down" aria-label="Move shot ${i+1} down">${icon('down')}</button></div>`:''}</div><div class="shot-notes"><span class="shot-cue-label">${shot.done?'IN THE CAN':'SCRIPT / ACTION'}</span>${readOnly?`<p>${escapeHTML(shot.notes||'No notes for this shot.')}</p>`:`<textarea data-shot-note="${shot.id}" aria-label="Notes for shot ${i+1}" rows="3" placeholder="What will you cover in this shot? Add your talking points, action, or filming notes…">${escapeHTML(shot.notes)}</textarea>`}</div><div class="shot-stamp-cell"><button class="stamp-target ${shot.done?'stamped':''}" data-stamp-shot="${shot.id}" ${readOnly?'disabled':''} aria-label="${shot.done?'Recorded':'Stamp'} shot ${i+1}" title="Click to stamp Recorded. Right-click to clear.">${stampHTML(shot.done)}</button>${shot.done&&shot.completedAt?`<small>${new Date(shot.completedAt).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}</small>`:''}</div><div class="shot-row-actions">${!readOnly?`<button class="icon-btn" data-delete-shot="${shot.id}" title="Remove shot" aria-label="Remove shot ${i+1}">${icon('trash')}</button>`:''}</div></div>`).join('')||'<div class="empty-state"><p>Add your first shot to start the sequence.</p></div>'}</div></div><div class="shot-sheet-footer"><span>${icon('cursor')}${readOnly?'A saved recording log. Reopen the sequence to make changes.':'Click a stamp area to mark Recorded. Right-click to clear it.'}</span><span>${readOnly?'Saved in history':`${total-done} shot${total-done===1?'':'s'} to go`}</span></div>`;
 if(!readOnly){$('#addShotRow').onclick=()=>addShot(seq.id);$('#embedShotSequence').onclick=()=>embedSequence(seq.id);$$('[data-shot-note]').forEach(el=>{el.onfocus=()=>checkpoint();el.oninput=()=>{const shot=seq.shots.find(s=>s.id===el.dataset.shotNote);shot.notes=el.value;save()}});$$('[data-stamp-shot]').forEach(b=>bindStamp(b,seq.id,b.dataset.stampShot));$$('[data-delete-shot]').forEach(b=>b.onclick=()=>{checkpoint();seq.shots=seq.shots.filter(s=>s.id!==b.dataset.deleteShot);save();renderShots()});$$('[data-move-shot]').forEach(b=>b.onclick=()=>{const i=seq.shots.findIndex(s=>s.id===b.dataset.moveShot),j=i+Number(b.dataset.direction);if(j<0||j>=seq.shots.length)return;checkpoint();[seq.shots[i],seq.shots[j]]=[seq.shots[j],seq.shots[i]];save();renderShots()})}
 else{$('#backShotHistory').onclick=()=>{shotHistoryId=null;renderShots()};$('#reopenShotSequence').onclick=()=>{checkpoint();seq.archived=false;seq.completedAt=null;if(seq.shots.length){seq.shots.at(-1).done=false;seq.shots.at(-1).completedAt=null}shotContentId=seq.contentId;shotMode='active';shotHistoryId=null;save();renderShots();toast('Sequence reopened. Your earlier takes are still recorded.')}}
}
function bindStamp(button,seqId,shotId){button.onclick=e=>{e.stopPropagation();setShotDone(seqId,shotId,true)};button.oncontextmenu=e=>{e.preventDefault();e.stopPropagation();setShotDone(seqId,shotId,false)};button.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopPropagation();const seq=sequences().find(s=>s.id===seqId),shot=seq?.shots.find(s=>s.id===shotId);if(shot)setShotDone(seqId,shotId,!shot.done)}}}
function setShotDone(seqId,shotId,done){const seq=sequences().find(s=>s.id===seqId),shot=seq?.shots.find(s=>s.id===shotId);if(!shot||shot.done===done)return;checkpoint();shot.done=done;shot.completedAt=done?new Date().toISOString():null;if(!done){seq.archived=false;seq.completedAt=null}const complete=seq.shots.length>0&&seq.shots.every(s=>s.done);if(complete){seq.archived=true;seq.completedAt=new Date().toISOString();seq.contentTitle=state.topics.find(t=>t.id===seq.contentId)?.title||seq.contentTitle}save();beep(done?'stamp':'disconnect');if(tab==='shots')renderShotSheet(seq,false);else if(tab==='whiteboard')renderNodes();if(complete){celebrateWrap();clearTimeout(shotArchiveTimer);shotArchiveTimer=setTimeout(()=>{if(!seq.archived)return;if(tab==='shots'){shotMode='history';shotHistoryId=null;renderShots()}else if(tab==='whiteboard')renderNodes();toast('Every shot recorded. Sequence saved to History.')},650)}}
function addShot(seqId){const seq=sequences().find(s=>s.id===seqId);if(!seq)return;checkpoint();seq.shots.push(makeShot());seq.archived=false;seq.completedAt=null;save();if(tab==='shots')renderShots();else renderNodes()}
function openShotSequence(id){const seq=sequences().find(s=>s.id===id);if(!seq)return toast('This shot list could not be found.');if(state.boards.some(b=>b.id===seq.boardId))state.activeBoard=seq.boardId;shotContentId=seq.contentId;shotMode=seq.archived?'history':'active';shotHistoryId=seq.archived?seq.id:null;switchTab('shots')}
