function embedSequence(seqId){const seq=sequences().find(s=>s.id===seqId),b=state.boards.find(b=>b.id===seq?.boardId);if(!seq||!b)return toast('The research board for this content is unavailable.');let n=b.nodes.find(n=>n.type==='sequencer');if(n&&n.sequenceId!==seq.id){const linked=sequences().find(s=>s.id===n.sequenceId);if(linked)return embedSequence(linked.id);n.sequenceId=seq.id}if(!n){checkpoint();const c=$('#canvas'),onBoard=tab==='whiteboard'&&board().id===b.id;n={id:uid(),type:'sequencer',sequenceId:seq.id,title:seq.contentTitle,x:Math.max(0,...b.nodes.map(item=>item.x+item.w*nodeScale(item).x))+75,y:80,w:460};b.nodes.push(n)}openBoard(b.id);selectedNode=n.id;renderNodes();requestAnimationFrame(()=>{const nodeElement=$(`[data-node="${n.id}"]`),z=Math.min(1,($('#canvas').clientHeight-170)/(nodeElement?.offsetHeight||400));moveCamera(($('#canvas').clientWidth-n.w*z)/2-n.x*z,95-n.y*z,z)});save();toast('Shot list linked. Changes stay in sync in both views.')}
function embeddedSequenceHTML(n){const seq=sequences().find(s=>s.id===n.sequenceId);if(!seq)return'<div class="node-body"><div class="node-title">Shot list unavailable</div><p class="node-description">Open Shot Sequencer to create a new list.</p></div>';return `<div class="node-body"><div class="node-label"><span>PRODUCTION SHOT LIST</span>${icon('sequence')}</div><div class="node-title">${escapeHTML(seq.contentTitle)}</div><div class="embedded-progress">${seq.shots.filter(s=>s.done).length} / ${seq.shots.length} recorded${seq.archived?' · Saved in history':''}</div><div class="embedded-rows"><div class="embedded-row embedded-head"><span>SHOT</span><span>SCRIPT & ACTION</span><span>TAKE</span></div>${seq.shots.map((s,i)=>`<div class="embedded-row ${s.done?'is-recorded':''}"><span class="embedded-number">${String(i+1).padStart(2,'0')}</span><textarea data-embedded-note="${s.id}" data-seq="${seq.id}" rows="2" aria-label="Notes for shot ${i+1}" placeholder="What will you capture?">${escapeHTML(s.notes)}</textarea><button data-embedded-stamp="${s.id}" data-seq="${seq.id}" class="embedded-stamp ${s.done?'done':''}" title="Click to stamp. Right-click to clear." aria-label="Recording stamp for shot ${i+1}">${s.done?'<span>REC</span>':icon('clapper')}</button></div>`).join('')}</div><div class="embedded-footer"><button class="text-btn" data-embedded-add="${seq.id}">${icon('plus')}Add shot</button><button class="text-btn" data-open-sequence="${seq.id}">${seq.archived?'Open history':'Open sequencer'}${icon('arrow')}</button></div></div>`}
function bindEmbeddedSequences(){$$('[data-embedded-stamp]').forEach(b=>bindStamp(b,b.dataset.seq,b.dataset.embeddedStamp));$$('[data-embedded-note]').forEach(el=>{el.onfocus=()=>checkpoint();el.oninput=()=>{const seq=sequences().find(s=>s.id===el.dataset.seq),shot=seq?.shots.find(s=>s.id===el.dataset.embeddedNote);if(shot){shot.notes=el.value;save()}}});$$('[data-embedded-add]').forEach(b=>b.onclick=e=>{e.stopPropagation();addShot(b.dataset.embeddedAdd)});$$('[data-open-sequence]').forEach(b=>b.onclick=e=>{e.stopPropagation();openShotSequence(b.dataset.openSequence)})}
